#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static int color(const char *s) {
    const char *x[] = {"black", "brown", "red",    "orange", "yellow",
                       "green", "blue",  "violet", "grey",   "white"};
    for (int i = 0; i < 10; i++)
        if (!strcmp(s, x[i]))
            return i;
    return -1;
}
bool resistor_label(const char *const *c, size_t n, char *out, size_t size) {
    if (n == 1 && color(c[0]) == 0) {
        snprintf(out, size, "0 ohms");
        return true;
    }
    if (n != 4 && n != 5)
        return false;
    double v = 0;
    for (size_t i = 0; i < n - 2; i++) {
        int d = color(c[i]);
        if (d < 0)
            return false;
        v = 10 * v + d;
    }
    int m = color(c[n - 2]);
    if (m < 0)
        return false;
    v *= pow(10, m);
    const char *unit = "ohms";
    if (v >= 1e6) {
        v /= 1e6;
        unit = "megaohms";
    } else if (v >= 1000) {
        v /= 1000;
        unit = "kiloohms";
    }
    const char *names[] = {"grey",  "violet", "blue", "green",
                           "brown", "red",    "gold", "silver"};
    double ts[] = {.05, .1, .25, .5, 1, 2, 5, 10};
    for (int i = 0; i < 8; i++)
        if (!strcmp(c[n - 1], names[i])) {
            snprintf(out, size, "%g %s ±%g%%", v, unit, ts[i]);
            return true;
        }
    return false;
}

