#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    char o[100];
    const char *a[] = {"orange", "orange", "red", "grey"};
    assert(resistor_label(a, 4, o, 100) && !strcmp(o, "3.3 kiloohms ±0.05%"));
    const char *b[] = {"orange", "red", "orange", "blue", "violet"};
    assert(resistor_label(b, 5, o, 100) && !strcmp(o, "323 megaohms ±0.1%"));
    const char *z[] = {"black"};
    assert(resistor_label(z, 1, o, 100) && !strcmp(o, "0 ohms"));
    {
        const char *values[] = {"orange", "orange", "black", "red"};
        char actual[1000];
        assert(resistor_label(values, 4, actual, sizeof actual));
        assert(!strcmp(actual, "33 ohms ±2%"));
    }
    {
        const char *values[] = {"blue", "grey", "brown", "violet"};
        char actual[1000];
        assert(resistor_label(values, 4, actual, sizeof actual));
        assert(!strcmp(actual, "680 ohms ±0.1%"));
    }
    {
        const char *values[] = {"red", "black", "red", "green"};
        char actual[1000];
        assert(resistor_label(values, 4, actual, sizeof actual));
        assert(!strcmp(actual, "2 kiloohms ±0.5%"));
    }
    {
        const char *values[] = {"green", "brown", "orange", "grey"};
        char actual[1000];
        assert(resistor_label(values, 4, actual, sizeof actual));
        assert(!strcmp(actual, "51 kiloohms ±0.05%"));
    }
    {
        const char *values[] = {"black"};
        char actual[1000];
        assert(resistor_label(values, 1, actual, sizeof actual));
        assert(!strcmp(actual, "0 ohms"));
    }
    {
        const char *values[] = {"orange", "orange", "yellow", "black", "brown"};
        char actual[1000];
        assert(resistor_label(values, 5, actual, sizeof actual));
        assert(!strcmp(actual, "334 ohms ±1%"));
    }
    {
        const char *values[] = {"red", "green", "yellow", "yellow", "brown"};
        char actual[1000];
        assert(resistor_label(values, 5, actual, sizeof actual));
        assert(!strcmp(actual, "2.54 megaohms ±1%"));
    }
    {
        const char *values[] = {"blue", "grey", "white", "brown", "brown"};
        char actual[1000];
        assert(resistor_label(values, 5, actual, sizeof actual));
        assert(!strcmp(actual, "6.89 kiloohms ±1%"));
    }
    {
        const char *values[] = {"violet", "orange", "red", "grey"};
        char actual[1000];
        assert(resistor_label(values, 4, actual, sizeof actual));
        assert(!strcmp(actual, "7.3 kiloohms ±0.05%"));
    }
    {
        const char *values[] = {"brown", "red", "orange", "green", "blue"};
        char actual[1000];
        assert(resistor_label(values, 5, actual, sizeof actual));
        assert(!strcmp(actual, "12.3 megaohms ±0.25%"));
    }
    {
        const char *values[] = {"brown", "black", "brown", "yellow", "violet"};
        char actual[1000];
        assert(resistor_label(values, 5, actual, sizeof actual));
        assert(!strcmp(actual, "1.01 megaohms ±0.1%"));
    }
    {
        const char *values[] = {"brown", "black", "red", "red"};
        char actual[1000];
        assert(resistor_label(values, 4, actual, sizeof actual));
        assert(!strcmp(actual, "1 kiloohms ±2%"));
    }
    return 0;
}
